/// <summary>
/// Bug 340986: E2E - Demand - CB201 - Post Provision Batch Job unsuccessful + Full Rebate Value = Write Off
/// </summary>
[
SysOperationJournaledParametersAttribute(true)
]
public class METTAMRebatePostController_Provision extends TAMRebatePostController
{   
}

Method.Source:
/// <summary>
/// When this is manually created from the batch job journal, we need to default the RebateTransactionType (hidden) to the right value
/// </summary>
/// <returns></returns>
protected container packDataContractInfoObjects()
{
    container ret;

    ret = super();

    ret = METTAMRebateContractHelper::updateRebateTransactionTypeInPackedContract(ret, TAMRebateTransactionType::Provision);

    // Bug 340352: [MS] E2E - RE-0031 Vendor Rebate - Batch Job Failed for Posting. MS SR# - 2603010030001346
    ret = METTAMRebateContractHelper::updateShowAutoSetDateInPackedContract(ret, true);

    return ret;
}

/// <summary>
///
/// </summary>
